-- MoonMod Pack: the MoonMod mods in one script.
-- GENERATED by tools/pack/build_pack.py from mods/<part>/main.lua. Do not edit here: edit the part's own folder,
-- then build again.
--
-- Each part's script is handed to moonmod.part.run as source: the engine compiles it as a chunk of its own (named
-- after its file, so errors give the part's own line numbers) and runs it as its own owner (its id, settings, saved
-- data and what it registers), only when the part is switched on. Each part's globals stay its own (part_env).
local PACK_ENV = _ENV

local function part_env(id)
  local base = moonmod
  local own = setmetatable({game = setmetatable({mod_id = id}, {__index = base.game})}, {__index = base})
  return setmetatable({moonmod = own}, {__index = PACK_ENV})
end

-- moonmod:part moonmod.autosave
moonmod.part.run("moonmod.autosave", [[
local function apply()
  local enabled = moonmod.settings.get("enabled") ~= false
  local result, err = game.save.autosave_set({enabled = enabled})
  if not result then
    moonmod.log("warn", "Autosave setting could not be applied: " .. tostring(type(err) == "table" and err.message or err))
  end
end

apply()
moonmod.on("settings.changed", function(event)
  if event.id == "enabled" then apply() end
end)
]], part_env("moonmod.autosave"), "moonmod.autosave/main.lua")
-- moonmod:end

-- moonmod:part moonmod.controls
moonmod.part.run("moonmod.controls", [[
-- Keyboard conveniences for Chronicle dungeon play. Native options remain
-- responsible for the game's own controller/keyboard bindings.
local function setting(id, fallback)
  local value = moonmod.settings.get(id)
  return type(value) == "string" and value or fallback
end

local actions = {}
local quick_keys = {
  setting("quick_1_key", "1"),
  setting("quick_2_key", "2"),
  setting("quick_3_key", "3")
}
local party_ids = {"toan", "xiao", "goro", "ruby", "ungaga", "osmond"}

for slot = 1, 3 do actions[#actions + 1] = {id = "quick_item_" .. slot, kind = "item", slot = slot} end
for index, character in ipairs(party_ids) do
  actions[#actions + 1] = {id = "party_member_" .. index, kind = "party", character = character}
end
actions[#actions + 1] = {id = "first_person_toggle", kind = "camera"}
actions[#actions + 1] = {id = "town_cycle", kind = "town_cycle"}

local function bind_actions()
  for slot = 1, 3 do
    assert(game.input.bind({id = "quick_item_" .. slot, keys = {setting("quick_" .. slot .. "_key", tostring(slot))}}))
  end
  for index = 1, #party_ids do
    assert(game.input.bind({id = "party_member_" .. index,
      keys = {setting("party_" .. index .. "_key", tostring(index + 3))}}))
  end
  assert(game.input.bind({id = "first_person_toggle", keys = {setting("first_person_key", "V")}}))
  -- Select is left to the game (it opens Georama); Backspace cycles town characters.
  assert(game.input.bind({id = "town_cycle", keys = {"Backspace"}}))
end
bind_actions()
moonmod.on("settings.changed", bind_actions)

local function notify(message)
  game.ui.notify({message = message:sub(1, 190)})
end

moonmod.on("game.tick", function()
  local world = game.world.get()
  local in_dungeon = world ~= nil and world.context == "dungeon"
  local in_town = world ~= nil and world.context == "georama" and type(world.map_id) == "number" and world.map_id >= 0 and world.map_id < 200
  game.input.wheel_mode_set({mode = in_dungeon and 0 or 1})
  for _, action in ipairs(actions) do
    local press = game.input.consume({id = action.id})
    if press and press.pressed then
      if action.kind == "item" and in_dungeon then
        local selected, err = game.items.quick_slot_use({slot = action.slot})
        if not selected then notify("Quick item unavailable: " .. tostring(type(err) == "table" and err.message or err)) end
      elseif action.kind == "party" and (in_dungeon or in_town) then
        local changed, err
        if in_dungeon then changed, err = game.party.set_active({id = action.character})
        else changed, err = game.party.town_set_active({id = action.character}) end
        if not changed then notify("Party switch unavailable: " .. tostring(type(err) == "table" and err.message or err)) end
      elseif action.kind == "camera" and in_dungeon then
        local toggled, err = game.render.first_person_toggle()
        if not toggled then notify("First-person view unavailable: " .. tostring(type(err) == "table" and err.message or err)) end
      elseif action.kind == "town_cycle" and in_town then
        local current = game.party.town_active()
        if current and type(current.id) == "string" then
          local index = 1
          for i, id in ipairs(party_ids) do if id == current.id then index = i;break end end
          local switched = false
          -- Only characters who have joined the party.
          local joined = {}
          local roster = game.party.list()
          for _, member in ipairs(roster and (roster.members or roster) or {}) do
            if type(member) == "table" and member.id then joined[member.id] = true end
          end
          for step = 1, #party_ids - 1 do
            local candidate = party_ids[((index - 1 + step) % #party_ids) + 1]
            local result = joined[candidate] and game.party.town_set_active({id = candidate})
            if result then switched = true;break end
          end
          if not switched then notify("No other joined town character is available") end
        end
      end
    end
  end
end)
]], part_env("moonmod.controls"), "moonmod.controls/main.lua")
-- moonmod:end

-- moonmod:part moonmod.expanded-town
moonmod.part.run("moonmod.expanded-town", [[
local enabled = false
local chord_down = false

local function setting(id, fallback)
  local value = moonmod.settings.get(id)
  return type(value) == "number" and value or fallback
end

local function bind()
  assert(game.input.bind({id = "town_overhead_key", keys = {moonmod.settings.get("town_camera_key") or "O"}}))
  assert(game.input.bind({id = "town_overhead_l1", keys = {"Gamepad:leftshoulder"}}))
  assert(game.input.bind({id = "town_overhead_l3", keys = {"Gamepad:leftstick"}}))
end
bind()
moonmod.on("settings.changed", bind)

local function town_context(world)
  return world and world.context == "georama"
end

local function set_enabled(value, notify)
  value = not not value
  if enabled == value then return true end
  local changed, err = game.render.town_camera_set({
    enabled = value,
    height = setting("camera_height", 90),
    back = setting("camera_back", 22)
  })
  if not changed then
    game.ui.notify({message = "Town camera unavailable: " .. tostring(type(err) == "table" and err.message or err)})
    return false
  end
  enabled = value
  if notify then game.ui.notify({message = enabled and "Overhead town camera" or "Town camera restored"}) end
  return true
end

game.ui.register({
  id = "toggle_town_camera",
  label = "Toggle Overhead Town Camera",
  description = "Toggle the overhead camera while walking in a town"
})

moonmod.on("ui.action", function(action)
  if action.id ~= "toggle_town_camera" then return end
  if not town_context(game.world.get()) then
    game.ui.notify({message = "Enter a town to use the overhead camera"})
    return
  end
  set_enabled(not enabled, true)
end)

moonmod.on("game.tick", function()
  local world = game.world.get()
  if not town_context(world) then
    if enabled then set_enabled(false, false) end
    chord_down = false
    game.input.consume({id = "town_overhead_key"})
    game.input.consume({id = "town_overhead_l1"})
    game.input.consume({id = "town_overhead_l3"})
    return
  end

  local key = game.input.consume({id = "town_overhead_key"})
  local l1 = game.input.state({id = "town_overhead_l1"})
  local l3 = game.input.state({id = "town_overhead_l3"})
  local chord = l1 and l1.down and l3 and l3.down or false
  if (key and key.pressed) or (chord and not chord_down) then set_enabled(not enabled, true) end
  chord_down = chord
end)

moonmod.log("info", "Expanded Town Camera initialized (O or L1+L3)")
]], part_env("moonmod.expanded-town"), "moonmod.expanded-town/main.lua")
-- moonmod:end

-- moonmod:part moonmod.modern-cloud
moonmod.part.run("moonmod.modern-cloud", [[
-- Modern Cloud: quality of life for Chronicle's story game. Every part is a setting; see README.md.
local REPAIR_POWDER = 177
local REPAIR_AT = 3      -- durability points left when the guard steps in: one hit takes one or two
local CHECK_EVERY = 10   -- frames between weapon and water checks

local function try(fn, ...)
  if type(fn) ~= "function" then return nil end
  local ok, a, b = pcall(fn, ...)
  if ok then return a, b end
  return nil, a
end

local function setting(id, fallback)
  local v = moonmod.settings.get(id)
  if v == nil then return fallback end
  return v
end

local function notify(message) try(game.ui.notify, {message = message}) end

-- Gauntlet runs and other sandbox sessions are their own game: Modern Cloud sits them out.
local in_sandbox = false

-- Tuning -----------------------------------------------------------------------------------------------------------
local function tuning()
  local thirst = setting("thirst", 50)
  return {
    thirst_drain = math.max(0.25, thirst / 100),
    durability_wear = setting("wear", 75) / 100,
    map_reveal = setting("map_reveal", false) and true or false,
    monster_reveal = setting("monster_reveal", false) and true or false,
    swap_delay = setting("swap_speed", 50) / 100,
    run_speed = setting("run_speed", 100) / 100,
  }
end

local function apply()
  if in_sandbox then try(game.player.tuning_clear); return end
  local ok, err = try(game.player.tuning_set, tuning())
  if not ok then moonmod.log("warn", "tuning_set refused: " .. tostring(type(err) == "table" and err.message or err)) end
end

-- Quick item keys --------------------------------------------------------------------------------------------------
local QUICK = {"1", "2", "3"}
local function bind_keys()
  for i, key in ipairs(QUICK) do
    if setting("quick_keys", true) then try(game.input.bind, {id = "quick_" .. i, keys = {key}})
    else try(game.input.unbind, {id = "quick_" .. i}) end
  end
end

-- Weapon guard ------------------------------------------------------------------------------------------------------
-- The warning steps are kept per weapon (character, slot, item) so each fires once as the weapon wears down, and
-- again after a repair.
local warned = {}
local function weapon_key(p) return p.character .. ":" .. tostring(p.weapon.slot) .. ":" .. tostring(p.weapon.item_no) end

local function guard_weapon(p)
  local mode = setting("weapon_guard", "Repair Powder")
  local w = p.weapon
  if mode == "Off" or not w or not w.id or type(w.durability) ~= "number" or (w.durability_max or 0) <= 0 then return end
  local key = weapon_key(p)
  local now, max = w.durability, w.durability_max
  local function set(value)
    return try(game.weapons.durability_set, {id = w.id, character = p.character, slot = w.slot, durability = value})
  end

  if now <= REPAIR_AT then
    if mode == "Repair Powder" then
      local removed = try(game.items.remove, {id = "chronicle:item:" .. REPAIR_POWDER, count = 1})
      if removed and (removed.removed or 0) > 0 then
        set(max); warned[key] = nil
        notify("Modern Cloud used a Repair Powder: your weapon is mended.")
        return
      end
      if not warned[key] or warned[key] < 3 then
        warned[key] = 3
        notify("Your weapon is about to break, and you have no Repair Powder!")
      end
    elseif mode == "Never break" then
      set(REPAIR_AT + 1)
      if not warned[key] or warned[key] < 3 then
        warned[key] = 3
        notify("Your weapon is worn out. It will not break, but repair it soon.")
      end
    elseif not warned[key] or warned[key] < 3 then
      warned[key] = 3
      notify("Your weapon is about to break!")
    end
    return
  end

  local pct = now * 100 / max
  local warn_at = setting("warn_at", 25)
  if pct < warn_at / 2 then
    if (warned[key] or 0) < 2 then warned[key] = 2; notify(string.format("Your weapon is badly worn (%d%%).", math.floor(pct))) end
  elseif pct < warn_at then
    if (warned[key] or 0) < 1 then warned[key] = 1; notify(string.format("Your weapon is wearing down (%d%%).", math.floor(pct))) end
  elseif warned[key] then
    warned[key] = nil -- repaired some other way
  end
end

-- Water -----------------------------------------------------------------------------------------------------------
local function keep_water(p)
  if setting("thirst", 50) ~= 0 then return end
  if type(p.water) == "number" and type(p.max_water) == "number" and p.water < p.max_water then
    try(game.player.set, {water = p.max_water, character = p.character})
  end
end

-- The tick ---------------------------------------------------------------------------------------------------------
local frame = 0
moonmod.on("game.tick", function()
  frame = frame + 1
  if in_sandbox then return end
  local world = try(game.world.get)
  local in_dungeon = world and world.context == "dungeon"
  if setting("quick_keys", true) then
    for i = 1, 3 do
      local press = try(game.input.consume, {id = "quick_" .. i})
      if press and press.pressed and in_dungeon then
        local ok, err = try(game.items.quick_slot_use, {slot = i})
        if not ok then
          local slot = (try(game.items.quick_slots) or {})[i]
          if slot and not slot.id then notify("Quick slot " .. i .. " is empty.") end
          if err then moonmod.log("info", "quick_slot_use: " .. tostring(type(err) == "table" and err.message or err)) end
        end
      end
    end
  end
  if not in_dungeon or frame % CHECK_EVERY ~= 0 then return end
  local p = try(game.player.get)
  if not p or not p.character then return end
  guard_weapon(p)
  keep_water(p)
end)

-- Sessions, settings, actions --------------------------------------------------------------------------------------
local function set_sandbox(now)
  if now == in_sandbox then return end
  in_sandbox = now
  apply()
end
-- A co-op visit (moonmod.coop) is the story game in the host's world: this mod plays on.
moonmod.on("game.session.started", function(e) if not (type(e) == "table" and e.kind == "visit") then set_sandbox(true) end end)
moonmod.on("game.session.ended", function() set_sandbox(false) end)
moonmod.on("settings.changed", function() bind_keys(); apply() end)

try(game.ui.register, {id = "check", label = "Check", description = "Show what Modern Cloud is doing right now"})
moonmod.on("ui.action", function(action)
  if action.id ~= "check" then return end
  local t = tuning()
  notify(string.format("Thirst x%.2f%s, wear x%.2f, guard: %s, switch x%.2f, walk x%.2f%s%s",
    t.thirst_drain, setting("thirst", 50) == 0 and " (kept full)" or "", t.durability_wear,
    setting("weapon_guard", "Repair Powder"), t.swap_delay, t.run_speed,
    t.map_reveal and ", map shown" or "", t.monster_reveal and ", monsters shown" or ""))
end)

local session = try(game.session.get)
in_sandbox = type(session) == "table" and session.kind == "sandbox"
bind_keys()
apply()
moonmod.log("info", "Modern Cloud ready")
]], part_env("moonmod.modern-cloud"), "moonmod.modern-cloud/main.lua")
-- moonmod:end

-- moonmod:part moonmod.sirfancybacon
moonmod.part.run("moonmod.sirfancybacon", [[
-- SirFancyBacon Mod Pack (moonmod.sirfancybacon): quality-of-life ideas from SirFancyBacon's Chronicle branches,
-- github.com/SirFancyBacon/Chronicle (qol-pack and floor-select), redone as a MoonMod mod. Credit for the ideas and
-- their rules is his; see README.md for what came from where and what still waits on engine support.

local AUTO_REPAIR_POWDER = 183
local REPAIR_POWDER = 177
local SE_WEAPON_REPAIR = 24
local BREAK_AT = 3      -- durability left when the bag's Auto Repair Powder steps in (a hit takes one or two)
local CHECK_EVERY = 10  -- frames between weapon checks

local function try(fn, ...)
  if type(fn) ~= "function" then return nil end
  local ok, a, b = pcall(fn, ...)
  if ok then return a, b end
  return nil, a
end
local function setting(id, fallback)
  local v = moonmod.settings.get(id)
  if type(v) ~= type(fallback) then return fallback end
  return v
end
local function notify(message) try(game.ui.notify, {message = message}) end
local function item_id(no) return "chronicle:item:" .. no end

-- The active weapon, when there is one to mend: {id, character, slot, now, max}.
local function active_weapon()
  local p = try(game.player.get)
  local w = type(p) == "table" and p.weapon or nil
  if not w or not w.id or type(w.durability) ~= "number" or (w.durability_max or 0) <= 0 then return nil end
  return {id = w.id, character = p.character, slot = w.slot, now = w.durability, max = w.durability_max}
end
local function mend(w)
  return try(game.weapons.durability_set, {id = w.id, character = w.character, slot = w.slot, durability = w.max})
end
local function take(no)
  local removed = try(game.items.remove, {id = item_id(no), count = 1})
  return type(removed) == "table" and (removed.removed or 0) > 0
end

-- Auto Repair Powder from the bag (qol-pack) --------------------------------------------------------------------------
-- Retail only lets an Auto Repair Powder save a weapon from a quick slot. His rule: with none in a quick slot, one in
-- the bag does the same. One in a quick slot is left to the game.
local function in_quick_slot(no)
  for _, slot in ipairs(try(game.items.quick_slots) or {}) do
    if type(slot) == "table" and slot.item_no == no and (slot.count or 0) > 0 then return true end
  end
  return false
end

local function auto_repair()
  if not setting("auto_repair", true) then return end
  local w = active_weapon()
  if not w or w.now > BREAK_AT or w.now >= w.max then return end
  if in_quick_slot(AUTO_REPAIR_POWDER) then return end
  if not take(AUTO_REPAIR_POWDER) then return end
  mend(w)
  try(game.audio.se_play, {se = SE_WEAPON_REPAIR})
  notify("An Auto Repair Powder from your bag mended your weapon.")
end

-- Repair Powder on a key (qol-pack's "Repair Powder in a quick slot") -----------------------------------------------
try(game.input.bind, {id = "repair", keys = {"T"}})
local function repair_key()
  local key = try(game.input.consume, {id = "repair"})
  if not (key and key.pressed) or not setting("repair_key", true) then return end
  local w = active_weapon()
  if not w then return end
  if w.now >= w.max then notify("Your weapon needs no repair.") return end
  if not take(REPAIR_POWDER) then notify("You have no Repair Powder.") return end
  mend(w)
  try(game.audio.se_play, {se = SE_WEAPON_REPAIR})
  notify("A Repair Powder mended your weapon.")
end

-- The floor list's warning (floor-select) ------------------------------------------------------------------------------
-- Floors whose limit is fixed by the floor itself (floor ids from 0, as the floor list counts them), then the limits a
-- save rolls (dungeons.floor_rules_get). The text is the warning the game gives on arrival, said before going in.
local FIXED = {
  [0] = {[6] = "abs_down", [10] = "xiao_only"},   -- Divine Beast Cave: B7, B11
  [1] = {[3] = "xiao_only", [11] = "goro_only"},  -- Wise Owl Forest: 4, 12
  [3] = {[4] = "goro_only", [12] = "ungaga_only"}, -- Sun and Moon Temple: 5, 13
}
local ONLY = {toan_only = "Toan", xiao_only = "Xiao", goro_only = "Goro", ruby_only = "Ruby",
              ungaga_only = "Ungaga", osmond_only = "Osmond"}
local function warning_for(dungeon, floor)
  local limit = FIXED[dungeon] and FIXED[dungeon][floor]
  if not limit then
    local rules = try(game.dungeons.floor_rules_get, {dungeon_id = dungeon, floor_id = floor})
    limit = type(rules) == "table" and rules.limit_zone_name or nil
  end
  if not limit or limit == "none" then return nil end
  if ONLY[limit] then return "! Only " .. ONLY[limit] .. " can go on this floor" end
  if limit == "abs_down" then return "! Weapons can't be changed on this floor" end
  if limit == "thirst" then return "! Thirst comes faster on this floor" end
  return "! This floor has a limit"
end

local shown = nil -- "dungeon:floor" the warning is shown for, or false for none
local function floor_warning()
  local s = setting("limit_warning", true) and try(game.dungeons.selection) or nil
  local key = type(s) == "table" and (s.dungeon_id .. ":" .. s.floor_id) or nil
  if key == shown then return end
  shown = key
  local text = key and warning_for(s.dungeon_id, s.floor_id)
  if text then try(game.render.layer_register, {id = "floor_limit", text = text})
  else try(game.render.layer_remove, {id = "floor_limit"}) end
end

moonmod.on("game.tick", function(e)
  local frame = type(e) == "table" and e.frame or 0
  repair_key()
  if frame % CHECK_EVERY == 0 then
    auto_repair()
    floor_warning()
  end
end)

-- For the tests.
return {warning_for = warning_for}
]], part_env("moonmod.sirfancybacon"), "moonmod.sirfancybacon/main.lua")
-- moonmod:end

-- moonmod:part moonmod.living-towns
moonmod.part.run("moonmod.living-towns", [[
-- Living Towns: bounties from the villagers, and stores that keep up with the story. See README.md.
--
-- The board: each adventure day (world.get().day) the towns post up to three bounties, each in a dungeon the story
-- has reached: hunt (fell monsters there), chests (open chests there), deeper (reach a floor past your deepest) or
-- fetch (bring an item, handed in at the board). Progress is kept per save slot. A bounty done is paid by its
-- villager, who waits by the exit gate on that dungeon's floors (or at the board in the Mod Manager).
-- The stores: a general store (a shop selling mostly goods) gains goods for each dungeon reached, through
-- shops.register_item, which claims no shop, so Dungeon+ and the Randomizer still own their lists.

local function try(fn, ...)
  if type(fn) ~= "function" then return nil end
  local ok, a, b = pcall(fn, ...)
  if ok then return a, b end
  return nil, a
end
local function setting(id, fallback)
  local v = moonmod.settings.get(id)
  if v == nil then return fallback end
  return v
end
local function notify(message, frames) try(game.ui.notify, {message = message:sub(1, 200), duration_frames = frames or 300}) end

local DUNGEONS = {[0] = "Divine Beast Cave", [1] = "Wise Owl Forest", [2] = "Shipwreck", [3] = "Sun and Moon Temple",
                  [4] = "Moon Sea", [5] = "Gallery of Time"}
-- Who asks, by the dungeon the bounty is in (each dungeon's own town)
local ASKERS = {
  [0] = {"Macho of Norune", "Paige of Norune", "Laura of Norune", "Norune's Mayor"},
  [1] = {"Pao of Matataki", "Cacao of Matataki", "a Matataki fisherman"},
  [2] = {"the Sheriff of Queens", "a Queens merchant", "a sailor of Queens"},
  [3] = {"the Chief of Muska Lacka", "a Muska Lacka shepherd"},
  [4] = {"a Yellow Drops farmer", "the Yellow Drops chief"},
  [5] = {"a voice from Brownboo"},
}
local FETCH = {{148, "Bread"}, {146, "Tasty Water"}, {155, "Cheese"}, {151, "Antidote Drink"}, {152, "Holy Water"},
               {177, "Repair Powder"}, {150, "Stamina Drink"}}
local REWARD_ITEMS = {{149, "Premium Chicken"}, {147, "Premium Water"}, {154, "Mighty Healing"}, {176, "Revival Powder"},
                      {183, "Auto Repair Powder"}, {178, "Powerup Powder"}, {95, "Garnet"}, {91, "Attack +1"}}

-- Goods a general store adds once each dungeon has been reached (cumulative)
local STOCK = {
  [1] = {147, 155, 151},           -- Wise Owl Forest: Premium Water, Cheese, Antidote Drink
  [2] = {149, 152, 150, 81, 82},   -- Shipwreck: Premium Chicken, Holy Water, Stamina Drink, Fire, Ice
  [3] = {154, 183, 83, 84},        -- Sun and Moon Temple: Mighty Healing, Auto Repair Powder, Thunder, Wind
  [4] = {176, 178, 85},            -- Moon Sea: Revival Powder, Powerup Powder, Holy
}

-- Per save slot -------------------------------------------------------------------------------------------------------
local in_sandbox, slot_key, slot = false, nil, nil
local function slots() local d = moonmod.storage.get("slots"); return type(d) == "table" and d or {} end
local function save()
  if not slot_key or not slot then return end
  local d = slots(); d[slot_key] = slot; moonmod.storage.set("slots", d)
end

-- How far the story has gone: the dungeons reached and how deep in each
local function progress()
  local reached, deepest = {}, {}
  for _, d in ipairs(try(game.dungeons.list) or {}) do
    local id, floor = tonumber(d.native_id), tonumber(d.deepest_floor_reached)
    if id and id <= 5 and floor and floor > 0 then reached[#reached + 1] = id; deepest[id] = floor end
  end
  table.sort(reached)
  return reached, deepest
end
local function tier() local r = progress(); return #r end

-- The board -----------------------------------------------------------------------------------------------------------
local function describe(b)
  local where = DUNGEONS[b.dungeon] or "a dungeon"
  local task
  if b.kind == "hunt" then task = string.format("Fell %d monsters in %s (%d/%d)", b.need, where, math.min(b.have, b.need), b.need)
  elseif b.kind == "chests" then task = string.format("Open %d chests in %s (%d/%d)", b.need, where, math.min(b.have, b.need), b.need)
  elseif b.kind == "deeper" then task = string.format("Reach floor %d of %s", b.need, where)
  else task = string.format("Bring %d %s", b.need, b.item_name) end
  return b.asker .. ": " .. task .. (b.done and " - done, collect it!" or "") .. string.format(" [%d Gilda]", b.gilda)
end

local function post_board(day)
  local reached, deepest = progress()
  slot.board, slot.day = {}, day
  if #reached == 0 then return end
  -- the same board for the same day of the same save: a seed from both
  math.randomseed(day * 7919 + #reached * 104729 + (slot.seed or 0))
  local kinds = {"hunt", "chests", "deeper", "fetch"}
  for i = 1, setting("bounty_count", 3) do
    local dungeon = reached[math.random(#reached)]
    local kind = kinds[math.random(#kinds)]
    local t = #reached
    local b = {id = day .. ":" .. i, kind = kind, dungeon = dungeon, have = 0, done = false, claimed = false,
               asker = ASKERS[dungeon][math.random(#ASKERS[dungeon])]}
    if kind == "hunt" then b.need = 8 + 4 * t + math.random(0, 6)
    elseif kind == "chests" then b.need = 3 + math.random(0, 2)
    elseif kind == "deeper" then b.need = math.max(2, (deepest[dungeon] or 1) + math.random(1, 2))
    else
      local f = FETCH[math.random(#FETCH)]
      b.item, b.item_name, b.need = f[1], f[2], math.random(1, 3)
    end
    b.gilda = math.floor((150 + 120 * t + (kind == "deeper" and 150 or 0)) * setting("reward", 100) / 100)
    local r = REWARD_ITEMS[math.random(math.min(#REWARD_ITEMS, 2 + t))]
    b.reward_item, b.reward_name = r[1], r[2]
    slot.board[i] = b
  end
  save()
end

local function complete(b)
  if b.done then return end
  b.done = true
  save()
  notify(b.asker .. "'s bounty is done. Collect it from the villager at a floor's exit, or at the board.", 360)
end

local function pay(b)
  if not b.done or b.claimed then return false end
  b.claimed = true
  try(game.economy.add, {amount = b.gilda})
  try(game.items.give, {id = "chronicle:item:" .. b.reward_item, count = 1})
  save()
  notify(string.format("%s thanks you: %d Gilda and a %s.", b.asker, b.gilda, b.reward_name), 360)
  return true
end

local function show_board()
  if not slot then notify("Load a game first"); return end
  if not slot.board or #slot.board == 0 then notify("The board is empty: the towns ask once a dungeon is reached."); return end
  for _, b in ipairs(slot.board) do if not b.claimed then notify(describe(b), 480) end end
  local any = false
  for _, b in ipairs(slot.board) do if not b.claimed then any = true end end
  if not any then notify("Every bounty on today's board is done. New ones tomorrow.") end
end

-- Stores ---------------------------------------------------------------------------------------------------------------
local stocked = {} -- "shop:item" added this session
local function general_stores()
  local out = {}
  for shop = 0, 17 do
    local got = try(game.shops.get, {shop_no = shop})
    local goods, weapons = 0, 0
    for _, e in ipairs(got and got.items or {}) do
      if (tonumber(e.item_no) or 0) >= 257 then weapons = weapons + 1 else goods = goods + 1 end
    end
    if goods >= 3 and goods > weapons then out[#out + 1] = {shop = shop, items = got.items} end
  end
  return out
end
local function restock()
  if not setting("stock", true) then return end
  local t = tier()
  if t <= 1 then return end
  for _, store in ipairs(general_stores()) do
    local have = {}
    for _, e in ipairs(store.items) do have[tonumber(e.item_no) or -1] = true end
    for level = 1, math.min(t - 1, 4) do
      for _, item in ipairs(STOCK[level]) do
        local key = store.shop .. ":" .. item
        if not have[item] and not stocked[key] and try(game.shops.register_item, {shop_no = store.shop, item_id = item}) then
          stocked[key] = true
        end
      end
    end
  end
end

-- Loading a save -------------------------------------------------------------------------------------------------------
local function load_slot()
  if in_sandbox then return end
  local identity = try(game.save.slot_id)
  local key = identity and identity.slot_id and (tostring(identity.slot_id) .. ":" .. tostring(identity.slot_generation)) or nil
  if not key and try(game.player.get) then key = "unsaved" end
  if key == slot_key then return end
  local previous = slot_key
  slot_key = key
  if not key then slot = nil; return end
  local d = slots()
  if previous == "unsaved" and key ~= "unsaved" and type(d[key]) ~= "table" and type(d.unsaved) == "table" then
    d[key], d.unsaved = d.unsaved, nil
  end
  slot = type(d[key]) == "table" and d[key] or {board = {}, day = -1, seed = math.random(0, 99999)}
  d[key] = slot
  moonmod.storage.set("slots", d)
  restock()
end

-- Events ---------------------------------------------------------------------------------------------------------------
local function bounty_here(kind)
  local w = try(game.world.get)
  if not (slot and w and w.context == "dungeon") then return {} end
  local out = {}
  for _, b in ipairs(slot.board or {}) do
    if b.dungeon == w.dungeon_id and not b.done and (kind == nil or b.kind == kind) then out[#out + 1] = b end
  end
  return out, w
end

moonmod.on("game.enemy_defeated", function()
  if in_sandbox then return end
  for _, b in ipairs(bounty_here("hunt")) do
    b.have = b.have + 1
    if b.have >= b.need then complete(b) end
  end
  save()
end)

moonmod.on("game.chest.opened", function(e)
  if in_sandbox or not e or e.chest == nil then return end
  for _, b in ipairs(bounty_here("chests")) do
    b.have = b.have + 1
    if b.have >= b.need then complete(b) end
  end
  save()
end)

moonmod.on("game.dungeon.generating", function(e)
  if in_sandbox or not slot or not e or e.back_floor or e.prebuild then return end
  -- deeper: the floor being built is floor_id + 1 in the game's counting
  for _, b in ipairs(slot.board or {}) do
    if b.kind == "deeper" and not b.done and b.dungeon == e.dungeon_id and (tonumber(e.floor_id) or 0) + 1 >= b.need then complete(b) end
  end
  -- a bounty of this dungeon waiting to be paid, or still open: its villager stands by the exit gate
  if setting("villager", true) then
    for _, b in ipairs(slot.board or {}) do
      if b.dungeon == e.dungeon_id and not b.claimed then
        try(game.world.dungeon_npc_set, {id = "bounty", model = "gedit/e01/chara/p02a.chr", place = "exit"})
        break
      end
    end
  end
end)

moonmod.on("game.dungeon_npc.near", function(e)
  if in_sandbox or not slot or not e or e.id ~= "bounty" then return end
  local w = try(game.world.get)
  local paid = false
  for _, b in ipairs(slot.board or {}) do
    if w and b.dungeon == w.dungeon_id and b.done and not b.claimed then paid = pay(b) or paid end
  end
  if not paid then
    for _, b in ipairs(slot.board or {}) do
      if w and b.dungeon == w.dungeon_id and not b.claimed then notify(describe(b), 360) end
    end
  end
end)

-- Actions --------------------------------------------------------------------------------------------------------------
for _, a in ipairs({{"board", "Bounty Board", "Today's bounties and how far along each is"},
                    {"hand_in", "Hand In and Collect", "Hand in fetched items, and collect every bounty that is done"}}) do
  try(game.ui.register, {id = a[1], label = a[2], description = a[3]})
end
moonmod.on("ui.action", function(a)
  if not a then return end
  load_slot()
  if in_sandbox then notify("Living Towns sits out challenge runs."); return end
  if a.id == "board" then show_board()
  elseif a.id == "hand_in" then
    if not slot then notify("Load a game first"); return end
    local any = false
    for _, b in ipairs(slot.board or {}) do
      if b.kind == "fetch" and not b.done then
        local r = try(game.items.remove, {id = "chronicle:item:" .. b.item, count = b.need})
        if r and (r.removed or 0) >= b.need then complete(b)
        elseif r and (r.removed or 0) > 0 then try(game.items.give, {id = "chronicle:item:" .. b.item, count = r.removed}) end
      end
      if pay(b) then any = true end
    end
    if not any then notify("Nothing to collect yet.") end
  end
end)

moonmod.on("game.session.started", function() in_sandbox = true; slot_key, slot = nil, nil end)
moonmod.on("game.session.ended", function() in_sandbox = false end)
do
  local s = try(game.session.get)
  in_sandbox = type(s) == "table" and s.kind == "sandbox"
end

local frame = 0
moonmod.on("game.tick", function()
  frame = frame + 1
  if in_sandbox or frame % 60 ~= 0 then return end
  load_slot()
  if not slot or not setting("bounties", true) then return end
  local w = try(game.world.get)
  local day = w and tonumber(w.day)
  if day and day ~= slot.day then
    post_board(day)
    if slot.board and #slot.board > 0 then notify("New bounties are posted in town (Mod Manager: Bounty Board).", 360) end
    restock()
  end
end)

load_slot()
moonmod.log("info", "Living Towns ready")
]], part_env("moonmod.living-towns"), "moonmod.living-towns/main.lua")
-- moonmod:end

-- moonmod:part moonmod.dungeon-plus
moonmod.part.run("moonmod.dungeon-plus", [[
-- Dungeon+: replay floors at Tiers 1-5 (Square/Triangle on the floor list), floor mutators, a bounty
-- on every floor, kill streaks, a bestiary and trophies in the Journal tab, enemies that get back up,
-- and the DarkCloud-Expanded weapon, price and shop data (BSD-2-Clause, (c) Gundorada Workshop).
-- Storage keys and trophy ids are the same as the previous version, so progress carries over.

local MAX_TIER = 5
local function try(fn, ...)
  local ok, value = pcall(fn, ...)
  if ok then return value end
  return nil
end
local function toast(message, frames) try(game.ui.notify, {message = message:sub(1, 190), duration_frames = frames or 240}) end

-- Sandbox modes (Dark Genie's Gauntlet) are their own game: during one, every handler below sits out.
local in_sandbox = false
local function on(name, handler)
  moonmod.on(name, function(...)
    if not in_sandbox then return handler(...) end
    if name == "ui.action" then toast("Dungeon+ sits out Dark Genie's Gauntlet runs") end
  end)
end
local function setting(id, fallback)
  local value = moonmod.settings.get(id)
  if type(value) ~= type(fallback) then return fallback end
  return value
end
local function clamp(v, lo, hi) v = tonumber(v) or lo; return math.max(lo, math.min(hi, math.floor(v))) end
local function store(key, value) moonmod.storage.set(key, value) end

-- Difficulty preset: scales the tunables below instead of replacing them.
local PRESETS = {
  relaxed  = {mutator = 0.6, revive = 0.4, tier_hp = 0.7, reward = 1.5, speed = 0.9},
  normal   = {mutator = 1.0, revive = 1.0, tier_hp = 1.0, reward = 1.0, speed = 1.0},
  hardcore = {mutator = 1.6, revive = 1.6, tier_hp = 1.4, reward = 0.75, speed = 1.15}
}
local function preset() return PRESETS[setting("difficulty_preset", "normal")] or PRESETS.normal end
local function reward(amount) return clamp(amount * setting("feats_reward_scale", 100) / 100 * preset().reward + 0.5, 0, 32767) end
local function pay(amount) if amount > 0 then try(game.economy.add, {amount = amount}) end end

-- Enemy labels used by the legacy Dungeon Feats bestiary and notifications.
-- The table is keyed by Chronicle's native monster-table index.
local ENEMY_NAMES={
 [0]="Master Jacket",[1]="Skeleton Soldier",[2]="Statue",[3]="Dasher",[4]="Werewolf",[5]="FliFli",[6]="Hornet",[7]="Halloween",
 [8]="Cannibal Plant",[9]="Earth Digger",[10]="Sunday",[11]="Monday",[12]="Tuesday",[13]="Wednesday",[14]="Thursday",[15]="Friday",[16]="Saturday",
 [17]="Witch Hellza",[18]="Witch Illza",[19]="Gunny",[20]="Gyon",[21]="Pirate's Chariot",[22]="Auntie Medu",[23]="Captain",[24]="Corcea",[25]="Golem",
 [26]="Mr. Blare",[27]="Dune",[28]="Titan",[29]="King Mimic (Divine Beast Cave)",[30]="Mimic (Divine Beast Cave)",
