  function MOVES.faster(m, k)
    local copy = {}
    for f, v in pairs(m) do copy[f] = v end
    copy.hits = {}
    for i, h in ipairs(m.hits or {}) do
      local hc = {}
      for f, v in pairs(h) do hc[f] = v end
      if hc.shot then hc.speed = math.min(10, (hc.speed or 5) * k) end
      copy.hits[i] = hc
    end
    return copy
  end
